#include "compositors/niri/niri_layout_theme.h"

#include "compositors/niri/niri_config_files.h"

#include <algorithm>
#include <format>

namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Helix from Control Center → Theme. Edits here are overwritten.\n"
        "// Owns niri layout colors (focus-ring, border, tab-indicator, insert-hint) and recent-windows.\n";

    void appendQuoted(std::string& out, std::string_view hex) {
      out += '"';
      out += hex;
      out += '"';
    }

    void appendColoredNode(
        std::string& out, std::string_view node, bool enabled, std::string_view activeHex, std::string_view inactiveHex,
        std::string_view urgentHex
    ) {
      out += "    ";
      out += node;
      out += " {\n";
      if (!enabled) {
        out += "        off\n";
      }
      out += "        active-color ";
      appendQuoted(out, activeHex);
      out += "\n        inactive-color ";
      appendQuoted(out, inactiveHex);
      if (!urgentHex.empty()) {
        out += "\n        urgent-color ";
        appendQuoted(out, urgentHex);
      }
      out += "\n    }\n";
    }

  } // namespace

  std::filesystem::path layoutThemeIncludePath() { return includePath(kLayoutThemeIncludeFileName); }

  std::string kdlForLayoutTheme(const LayoutThemeSettings& settings) {
    std::string body(kManagedHeader);
    body += "layout {\n";
    if (settings.gaps.has_value()) {
      const int gaps = std::clamp(*settings.gaps, 0, 64);
      body += "    gaps ";
      body += std::to_string(gaps);
      body += "\n";
    }
    if (settings.defaultColumnWidth.has_value()) {
      const double width = std::clamp(*settings.defaultColumnWidth, 0.15, 1.0);
      body += std::format("    default-column-width {{ proportion {:.2f}; }}\n", width);
    }
    if (settings.struts.has_value()) {
      const int struts = std::clamp(*settings.struts, 0, 64);
      body += "    struts {\n        left ";
      body += std::to_string(struts);
      body += "\n        right ";
      body += std::to_string(struts);
      body += "\n        top ";
      body += std::to_string(struts);
      body += "\n        bottom ";
      body += std::to_string(struts);
      body += "\n    }\n";
    }
    appendColoredNode(
        body, "focus-ring", settings.focusRing, settings.activeColorHex, settings.inactiveColorHex,
        settings.urgentColorHex
    );
    appendColoredNode(
        body, "border", settings.border, settings.activeColorHex, settings.inactiveColorHex, settings.urgentColorHex
    );
    appendColoredNode(
        body, "tab-indicator", true, settings.activeColorHex,
        settings.tabInactiveColorHex.empty() ? settings.inactiveColorHex : settings.tabInactiveColorHex,
        settings.urgentColorHex
    );
    body += "    insert-hint {\n        color ";
    appendQuoted(body, settings.insertHintColorHex.empty() ? settings.activeColorHex : settings.insertHintColorHex);
    body += "\n    }\n}\n\nrecent-windows {\n    highlight {\n        active-color ";
    appendQuoted(body, settings.activeColorHex);
    if (!settings.urgentColorHex.empty()) {
      body += "\n        urgent-color ";
      appendQuoted(body, settings.urgentColorHex);
    }
    body += "\n    }\n}\n";
    return body;
  }

  InstallResult saveNiriLayoutTheme(const LayoutThemeSettings& settings) {
    return saveNiriLayoutThemeInto(configPath(), settings);
  }

  InstallResult saveNiriLayoutThemeInto(const std::filesystem::path& configFile, const LayoutThemeSettings& settings) {
    InstallResult result;
    if (configFile.empty()) {
      result.error = "niri config path is unknown";
      return result;
    }
    std::error_code ec;
    if (!std::filesystem::exists(configFile, ec) || ec) {
      result.error = "niri config not found";
      return result;
    }
    const auto include = configFile.parent_path() / std::string(kLayoutThemeIncludeFileName);
    if (!writeFile(include, kdlForLayoutTheme(settings), result.error)) {
      return result;
    }
    if (!appendInclude(configFile, kLayoutThemeIncludeFileName, result.error)) {
      return result;
    }
    result.ok = true;
    result.added = 1;
    return result;
  }

} // namespace compositors::niri
